   printf("Enter %d integers\n", size);

   for ( c = 0 ; c < size ; c++ )
      scanf("%d", &array[c]);

   minimum = array[0];

   // Optimization
   int start  = 1;
   int end  = size-1;
   while(start <= end){
     int mid = (start + end)/2;
