    for(originalNum = lower + 1; originalNum < upper; originalNum++) 
    { 
        num = originalNum; 
        while(num != 0) 
        { 
            num /= 10; 
            n++; 
        }  

        num = originalNum; 
        int sum = 0; 

        // Calculates the sum of the nth power of the digits 
        while(num != 0) 
        { 
            remainder = num % 10; 
            sum += Math.pow(remainder, n); 
